import * as T from './three.module.js';
// Actor obstacles retain oriented local boxes. World AABBs falsely enclosed the
// focus point on bends and forced every manual view into the overhead fallback.
export function cameraClear(target,eye,obstacles,padding=.45){for(const obstacle of obstacles){let from=target,to=eye,box=obstacle;if(obstacle.box){const inverse=obstacle.matrix.clone().invert();from=target.clone().applyMatrix4(inverse);to=eye.clone().applyMatrix4(inverse);box=obstacle.box;}const expanded=box.clone().expandByScalar(padding);if(expanded.containsPoint(to))return false;const delta=to.clone().sub(from),length=delta.length();if(length<.01)return false;const ray=new T.Ray(from,delta.normalize()),hit=ray.intersectBox(expanded,new T.Vector3());if(hit&&hit.distanceTo(from)<length-.1)return false;}return true;}
export function safeRaceCamera(target,desired,forward,obstacles){const side=new T.Vector3(-forward.z,0,forward.x),distance=desired.distanceTo(target),candidates=[desired.clone(),desired.clone().add(new T.Vector3(0,2,0)),target.clone().addScaledVector(forward,-Math.max(5,distance*.8)).addScaledVector(side,3.5).add(new T.Vector3(0,4.5,0)),target.clone().addScaledVector(forward,-Math.max(5,distance*.8)).addScaledVector(side,-3.5).add(new T.Vector3(0,4.5,0)),target.clone().add(new T.Vector3(0,10,0)).addScaledVector(forward,-5)];for(const candidate of candidates)if(cameraClear(target,candidate,obstacles))return candidate;const fallback=target.clone().addScaledVector(forward,-5);fallback.y=Math.max(target.y+12,...obstacles.map(b=>b.box?b.box.clone().applyMatrix4(b.matrix).max.y+2:b.max.y+2));return fallback;}
